try{const p=JSON.parse(localStorage.getItem('mylibrary-appearance-1')||'{}');document.documentElement.dataset.theme=p.theme==='dark'||(p.theme!=='light'&&matchMedia('(prefers-color-scheme:dark)').matches)?'dark':'light';}catch{document.documentElement.dataset.theme=matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light';}
